codeSnippet.code:
struct Thermostat {
    var temperature: Int = 70 {
        didSet {
            print("changed from \(oldValue) to \(temperature)")
        }
    }
}

var t = Thermostat()
t.temperature = 72

var handlers: [() -> Void] = []
for i in 0..<3 {
    handlers.append { print(i) }
}
for handler in handlers {
    handler()
}

class Animal {
    static func describe() -> String { "an animal" }
}

class Dog: Animal {
    override static func describe() -> String { "a dog" }
}

@propertyWrapper
struct Clamped {
    private var value: Int
    let range: ClosedRange<Int>

    var wrappedValue: Int {
        get { value }
        set { value = min(max(newValue, range.lowerBound), range.upperBound) }
    }

    var projectedValue: Bool { value == range.upperBound }

    init(wrappedValue: Int, _ range: ClosedRange<Int>) {
        self.range = range
        self.value = min(max(wrappedValue, range.lowerBound), range.upperBound)
    }
}

struct Player {
    @Clamped(0...100) var health = 100
}
